//! Raw bindings to libghostty-vt (generated by bindgen from `ghostty/vt.h`).
//!
//! Structs with a `size` field must have it set to their `size_of` before
//! use, as C's `GHOSTTY_INIT_SIZED` does; [`sized`] does that.

#![allow(non_upper_case_globals, non_camel_case_types, non_snake_case, clippy::all)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));

/// `GHOSTTY_INIT_SIZED`: a zeroed `T` with its leading `size` field set.
///
/// # Safety
/// `T` must be a libghostty sized struct: plain data whose first field is a `usize` named `size`.
pub unsafe fn sized<T: Default>() -> T {
    let mut v = T::default();
    // SAFETY: the caller promises the first field is a usize.
    unsafe { *(&mut v as *mut T as *mut usize) = std::mem::size_of::<T>() };
    v
}
